from solution import power


def test_issue_example_3_4():
    """Example: assert power(3,4) == 81."""
    assert power(3, 4) == 81  # 3*3*3*3=81


def test_issue_exponent_zero_is_one():
    """Calculate 'a' to the power 'b': any a to the power 0 is 1."""
    assert power(10, 0) == 1  # 10**0=1 by definition


def test_issue_exponent_one_is_base():
    """Calculate 'a' to the power 'b': a to the power 1 is a."""
    assert power(7, 1) == 7  # single factor 7=7


def test_issue_zero_base_positive_exponent():
    """Calculate 'a' to the power 'b': 0 to a positive power is 0."""
    assert power(0, 5) == 0  # 0*0*0*0*0=0


def test_issue_one_base_large_exponent():
    """Calculate 'a' to the power 'b': 1 to any power is 1."""
    assert power(1, 50) == 1  # 1*1*...*1 (50 times)=1


def test_issue_negative_base_odd_exponent():
    """Calculate 'a' to the power 'b': negative base with odd exponent is negative."""
    assert power(-3, 3) == -27  # (-3)*(-3)*(-3)=-27


def test_issue_negative_base_even_exponent():
    """Calculate 'a' to the power 'b': negative base with even exponent is positive."""
    assert power(-3, 2) == 9  # (-3)*(-3)=9


def test_issue_negative_exponent_reciprocal():
    """Calculate 'a' to the power 'b': negative exponent gives reciprocal."""
    assert power(2, -3) == 0.125  # 1/(2*2*2)=1/8=0.125


def test_issue_negative_base_negative_exponent():
    """Calculate 'a' to the power 'b': negative base with negative exponent."""
    assert power(-2, -3) == -0.125  # 1/((-2)*(-2)*(-2))=1/(-8)=-0.125


def test_issue_power_of_two_ten():
    """Calculate 'a' to the power 'b': 2 to the power 10."""
    assert power(2, 10) == 1024  # 2*2*2*2*2*2*2*2*2*2=1024


def test_contract_keyword_names_a_and_b():
    """Public interface: power(a, b) takes parameters named a and b."""
    assert power(a=3, b=4) == 81  # 3*3*3*3=81


def test_contract_result_is_number():
    """Public interface: power(a, b) calculates a numeric value."""
    assert isinstance(power(2, 3), (int, float)) == True  # 2*2*2=8 is a number -> True
